353	                                                                  jint allocation_mode, jint log_to,
354	                                                                  jstring jpath, jlong pool_size) {
355	  try {
356	    // make sure the CUDA device is setup in the context
357	    cudaError_t cuda_status = cudaFree(0);
358	    cudf::jni::jni_cuda_check(env, cuda_status);
359	    int device_id;
360	    cuda_status = cudaGetDevice(&device_id);
361	    cudf::jni::jni_cuda_check(env, cuda_status);
362	
363	    bool use_pool_alloc = allocation_mode & 1;
364	    bool use_managed_mem = allocation_mode & 2;
365	    if (use_pool_alloc) {
366	      if (use_managed_mem) {
367	        Initialized_resource = rmm::mr::make_owning_wrapper<rmm::mr::pool_memory_resource>(
368	            std::make_shared<rmm::mr::managed_memory_resource>(), pool_size, pool_size);
369	        auto wrapped = make_tracking_adaptor(Initialized_resource.get(), RMM_ALLOC_SIZE_ALIGNMENT);
370	        Tracking_memory_resource.reset(wrapped);
371	      } else {
372	        Initialized_resource = rmm::mr::make_owning_wrapper<rmm::mr::pool_memory_resource>(
373	            std::make_shared<rmm::mr::cuda_memory_resource>(), pool_size, pool_size);
374	        auto wrapped = make_tracking_adaptor(Initialized_resource.get(), RMM_ALLOC_SIZE_ALIGNMENT);
375	        Tracking_memory_resource.reset(wrapped);
376	      }
377	    } else if (use_managed_mem) {
378	      Initialized_resource = std::make_shared<rmm::mr::managed_memory_resource>();
379	      auto wrapped = make_tracking_adaptor(Initialized_resource.get(), RMM_ALLOC_SIZE_ALIGNMENT);
380	      Tracking_memory_resource.reset(wrapped);
381	    } else {
382	      Initialized_resource = std::make_shared<rmm::mr::cuda_memory_resource>();
383	      auto wrapped = make_tracking_adaptor(Initialized_resource.get(), RMM_ALLOC_SIZE_ALIGNMENT);
384	      Tracking_memory_resource.reset(wrapped);
385	    }
386	    auto resource = Tracking_memory_resource.get();
387	    rmm::mr::set_default_resource(resource);
388	
389	    std::unique_ptr<logging_resource_adaptor<base_tracking_resource_adaptor>> log_result;
390	    switch (log_to) {
391	      case 1: // File
392	      {
393	        cudf::jni::native_jstring path(env, jpath);
394	        log_result.reset(new logging_resource_adaptor<base_tracking_resource_adaptor>(
395	            resource, path.get(), /*auto_flush=*/true));
396	      } break;
397	      case 2: // stdout
398	        log_result.reset(new logging_resource_adaptor<base_tracking_resource_adaptor>(
399	            resource, std::cout, /*auto_flush=*/true));
400	        break;
401	      case 3: // stderr
402	        log_result.reset(new logging_resource_adaptor<base_tracking_resource_adaptor>(
403	            resource, std::cerr, /*auto_flush=*/true));
404	        break;
405	    }
406	
407	    if (log_result) {
408	      if (Logging_memory_resource) {
409	        JNI_THROW_NEW(env, RMM_EXCEPTION_CLASS, "Internal Error logging is double enabled", )
410	      }
411	
412	      Logging_memory_resource = std::move(log_result);
413	      auto replaced_resource = rmm::mr::set_default_resource(Logging_memory_resource.get());
414	      if (resource != replaced_resource) {
415	        rmm::mr::set_default_resource(replaced_resource);
416	        Logging_memory_resource.reset(nullptr);
417	        JNI_THROW_NEW(env, RMM_EXCEPTION_CLASS,
418	                      "Concurrent modification detected while installing memory resource", );
419	      }

