429	JNIEXPORT void JNICALL Java_ai_rapids_cudf_Rmm_shutdownInternal(JNIEnv *env, jclass clazz) {
430	  try {
431	    cudf::jni::auto_set_device(env);
432	    set_java_device_memory_resource(env, nullptr, nullptr, nullptr);
433	    // Instead of trying to undo all of the adaptors that we added in reverse order
434	    // we just reset the base adaptor so the others will not be called any more
435	    // and then clean them up in really any order.  There should be no interaction with
436	    // RMM during this time anyways.
437	    Initialized_resource = std::make_shared<rmm::mr::cuda_memory_resource>();
438	    rmm::mr::set_default_resource(Initialized_resource.get());
439	    Logging_memory_resource.reset(nullptr);
440	    Tracking_memory_resource.reset(nullptr);
441	    cudf::jni::set_cudf_device(cudaInvalidDeviceId);
442	  }
443	  CATCH_STD(env, )
444	}
